def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_def = 0
    my_def = 0
    for a in opp:
        if a == 'D':
            opp_def += 1
    for a in me:
        if a == 'D':
            my_def += 1

    opp_coop = n - opp_def

    # last move
    last_opp = opp[-1]
    last_me = me[-1]

    # Early game: cooperate to establish mutual cooperation.
    if n < 5:
        # one early gentle probe at round 4 if opponent always cooperated
        if n == 4 and opp_def == 0:
            return 'D'
        return 'C'

    # If opponent is extremely defection-heavy, minimize losses with D.
    # Threshold reduces as match goes on.
    if opp_def * 3 >= n * 2:
        # rare probe for cooperation restoration
        if n % 13 == 0:
            return 'C'
        return 'D'

    # If opponent is nearly always defecting, just defect.
    if opp_def >= n - 1 and n >= 6:
        if n % 17 == 0:
            return 'C'
        return 'D'

    # Endgame exploitation: last rounds.
    remaining = 100 - n
    if remaining <= 1:
        # Final round: defect if opponent is likely to cooperate.
        if opp_coop * 3 >= n * 2:
            return 'D'
        return 'D'

    if remaining <= 4:
        # Near end: if opponent mostly cooperates, defect more.
        if opp_coop * 2 >= n:
            return 'D'
        if last_opp == 'C':
            return 'D'
        return 'D'

    if remaining <= 8:
        # Semi-endgame: defect if opponent seems forgiving/cooperative.
        if opp_def * 4 <= n and n >= 10:
            return 'D'
        if last_opp == 'C' and last_me == 'C':
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Main game: adaptive tit-for-tat with pattern exploitation.

    # Count recent statistics over last 8 rounds.
    window = history[-8:] if n >= 8 else history
    wlen = len(window)
    w_opp_def = 0
    w_my_def = 0
    for rec in window:
        if rec[1] == 'D':
            w_opp_def += 1
        if rec[0] == 'D':
            w_my_def += 1

    # Detect how opponent reacts after our defections.
    opp_after_my_def_c = 0
    opp_after_my_def_total = 0
    for i in range(1, n):
        if me[i - 1] == 'D':
            opp_after_my_def_total += 1
            if opp[i] == 'C':
                opp_after_my_def_c += 1

    forgiving = False
    if opp_after_my_def_total >= 2:
        if opp_after_my_def_c * 2 >= opp_after_my_def_total:
            forgiving = True

    # Detect how opponent reacts after their own defections (i.e., our response).
    # Track consecutive opponent defections.
    consec_opp_def = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            consec_opp_def += 1
        else:
            break

    # Opponent is highly cooperative: milk them with occasional defections.
    if opp_def == 0:
        # They always cooperate. Defect periodically.
        # Defect more often near the end but not too early.
        if n >= 12:
            # use a schedule: defect at increasing frequency
            period = 7 if n < 40 else 4
            if n % period == 0:
                return 'D'
        return 'C'

    # If opponent defected last round:
    if last_opp == 'D':
        # If opponent is generally cooperative and this is isolated, forgive.
        if opp_def * 5 <= n:
            # mostly cooperative opponent
            if consec_opp_def == 1 and rng.random() < 0.5:
                return 'C'
            if consec_opp_def >= 2:
                return 'D'
            return 'D'
        # If opponent has been defecting a lot, keep defecting.
        if opp_def * 2 >= n:
            return 'D'
        # moderate opponent: retaliate but forgive sometimes
        if consec_opp_def >= 3:
            return 'D'
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # last_opp == 'C'
    # If we defected last and they still cooperated, they may be forgiving.
    if last_me == 'D' and last_opp == 'C':
        # Exploit forgiving opponents more aggressively.
        if forgiving and remaining > 12:
            # defect again to extract more
            return 'D'
        return 'C'

    # Both cooperated last. Decide whether to defect.
    # If opponent is forgiving and mostly cooperative, exploit more.
    if forgiving and opp_def * 4 <= n and n >= 15:
        # Exploit with moderate frequency, increasing near end.
        if remaining <= 20:
            if n % 2 == 0:
                return 'D'
        else:
            if n % 5 == 0:
                return 'D'
        return 'C'

    # If opponent has shown recent defections but overall cooperative, cooperate.
    if opp_def * 3 <= n:
        return 'C'

    # Mixed opponent: check recent defection rate.
    if w_opp_def * 2 >= wlen:
        # recent opponent defecting a lot
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    if w_opp_def >= 1:
        # occasional defection: copy their last move with forgiveness
        if rng.random() < 0.15:
            return 'D'
        return 'C'

    return 'C'
